// STUB — Phase 8 Skeleton
// PURPOSE: Validate content draft against content-output.schema.json required fields
// SCHEMA REF: schemas/content-output.schema.json
// REQUIRED FIELDS: content_id, brand_id, brand_name, content_type, platform,
//   objective, target_audience, hook, caption, cta, approval_status,
//   created_by_agent, created_at
// NOTE: hashtags and human_review_required are NOT in schema — do not validate them

const inputData = $input.first().json;
const draft = inputData.contentDraft || {};

const requiredFields = [
  'content_id', 'brand_id', 'brand_name', 'content_type',
  'platform', 'objective', 'target_audience', 'hook',
  'caption', 'cta', 'approval_status', 'created_by_agent', 'created_at'
];

const missingFields = requiredFields.filter(f => !draft[f] || draft[f] === '');
const validationPass = missingFields.length === 0;
const validationErrors = missingFields.map(f => `SCHEMA_VALIDATION_FAIL: Missing required field: ${f}`);

return [{ json: { ...inputData, validation_pass: validationPass, validation_errors: validationErrors } }];

