  action_type: 'Content Draft',
  input_ref: inputData.content_request || 'STUB_INPUT',
  output_ref: draft.content_id || 'STUB_OUTPUT',
  status: 'Success',
  summary: 'Content Auto skeleton executed. Draft created with approval_status=Draft. No real AI call.',
  errors: (inputData.validation_errors && inputData.validation_errors.length) ? inputData.validation_errors : null,
  next_action: 'Send draft to approval queue. Owner to review and set approval_status=Approved before publishing.',
  owner_action_required: false
};

// STUB: Production code would write logEntry to Google Sheets or Supabase here
return [{ json: { ...inputData, logEntry, logWritten: true } }];
